// 《白塔日报》的氛围池。
//
// 报纸的主体就是这一池子字。AI 那条供稿是可选的, 池子是保底 —— 所以**池子必须大**:
// 一期抽 10 条, 池子 130 条的话大约十几期才会开始眼熟, 而重复的报纸比没有报纸更伤
// 沉浸感。这是这个模块唯一的真实成本, 也是它唯一值得写长的地方。
//
// 三条硬约束 (spec §2, 全是玩家给的):
//
//   ① **世界不围着玩家转。** 这里一个字都不提主角和诊所 —— 四大特区的政治、航线、
//      物价、讣告、广告, 世界自顾自运转才好看。想让报纸提到诊所, 只有一条路: 玩到
//      名声够高, 由 AI 自己写进「报纸供稿」里。开局就发奖状是最出戏的写法。
//   ② **不必强绑定剧情。** 这些都是背景音, 跟当下这一楼有没有关系都行。
//   ③ 素材锚在旧卡世界书上 (归档/白塔-原始备份.json), 四个特区、白塔的功能分区、
//      深渊 T1–T5、极南暗雨街区的黑市、年度节庆 —— 让读过世界书的玩家认得出来。
//
// ⚠ 别写具体日期 (「3 月 15 日」这种)。这张卡的历法是「霜降月第一日」那种, 跟公历
//   对不上, 写死了就直接穿帮。节日只提名字不提起止日。

export type 版面 = '要闻' | '社会' | '经济' | '讣告' | '广告' | '天气';

/** 报纸上的版面顺序。也是渲染顺序。 */
export const 版面次序: 版面[] = ['要闻', '社会', '经济', '讣告', '广告', '天气'];

/** 版面的显示名。`经济` 在报上写「经济·军事」。 */
export const 版面名: Record<版面, string> = {
  要闻: '要闻',
  社会: '社会',
  经济: '经济 · 军事',
  讣告: '讣告',
  广告: '分类广告',
  天气: '天气',
};

/** 每期每个版面抽几条。定死而不是随机, 是为了让版面的分量稳定 —— 要闻永远是 2 条, 讣告永远是 1 条。 */
export const 每版条数: Record<版面, number> = {
  要闻: 2,
  社会: 2,
  经济: 2,
  讣告: 1,
  广告: 2,
  天气: 1,
};

export type 季节 = '春' | '夏' | '秋' | '冬';

export interface 条目 {
  版面: 版面;
  标题: string;
  /** 报纸正文。两三句, 像报纸那样把话说完就停。 */
  正文: string;
  /** 只在这些季节出现。不给 = 全年都有。 */
  季?: 季节[];
  /** 只在 `世界.天气` 含有其中任一字时出现。不给 = 什么天气都可能登。 */
  天?: string[];
}

